	m_NewUV[0][3] = 0.0f;
	m_NewUV[1][0] = 0.99f;
	m_NewUV[1][1] = -0.99f;
	m_NewUV[1][2] = 1.0f;
	m_NewUV[1][3] = 0.0f;

	m_RGB[0][0] = 255.0f;
	m_RGB[0][1] = 255.0f;
	m_RGB[0][2] = 255.0f;
	m_RGB[0][3] = 100.0f;
	m_RGB[1][0] = 255.0f;
